import { Object3D, Mesh, PlaneGeometry, Vector2 } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  // Base Object3D
  const node = new Object3D();

  // Apply transform
  const pos = config.position ?? [0, 0, 0];
  const rot = config.rotation ?? [0, 0, 0];
  const scl = config.scale ?? [1, 1, 1];
  node.position.set(...pos);
  node.rotation.set(...rot);
  node.scale.set(...scl);

  // ----------------------------
  // Textured plane (artifact sprite)
  // ----------------------------
  const ATLAS = config.atlasRegion ?? { x: 0, y: 0, w: 512, h: 320 };
  const aspect = ATLAS.w / ATLAS.h;

  const geometry = new PlaneGeometry(aspect, 1);
  const texture = ctx.textureLoader('/prism-assets/chrome/ceramic-grain.map.png');

  // Configure UV offset / repeat based on atlas region (assumes texture size equals atlas size)
  if (texture && texture.image) {
    const img = texture.image;
    const texW = img.width || 1;
    const texH = img.height || 1;
    texture.offset.set(ATLAS.x / texW, 1 - (ATLAS.y + ATLAS.h) / texH);
    texture.repeat.set(ATLAS.w / texW, ATLAS.h / texH);
    texture.needsUpdate = true;
  }

  const material = new MeshBasicNodeMaterial({ map: texture });
  const plane = new Mesh(geometry, material);
  node.add(plane);

  // ----------------------------
  // MSDF Text rendering (label)
  // ----------------------------
  const text = config.textContent ?? '';
  if (text && ctx.fontAtlas && typeof ctx.fontAtlas.createTextMesh === 'function') {
    const textMesh = ctx.fontAtlas.createTextMesh(text, {
      // use design tokens where possible
      color: config.colors?.ink ?? '#16161d',
      font: 'display', // Lora serif per spec
      // approximate headline size (scene‑unit em height 0.34)
      size: 0.34,
      // place text slightly in front of the plane to avoid Z‑fighting
      position: new Vector2(0, 0.02)
    });
    if (textMesh) node.add(textMesh);
  }

  // ----------------------------
  // Cinematic primitives (if any)
  // ----------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[primitive.name];
      if (typeof fn === 'function') fn(node, primitive.params);
    }
  }

  // ----------------------------
  // Event handlers container (no interactions defined)
  // ----------------------------
  node.userData.handlers = {};

  // ----------------------------
  // Cleanup routine
  // ----------------------------
  node.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();
    // destroy any GSAP timelines that might have been created elsewhere
    gsap.killTweensOf(node);
    if (node.userData.handlers) {
      for (const key in node.userData.handlers) {
        const handler = node.userData.handlers[key];
        if (handler && typeof handler.dispose === 'function') handler.dispose();
      }
    }
  };

  return node;
}
